// measureCorpus counts the repository's source in lines.
//
// It counts git-tracked files, not everything on disk: build output, vendored
// dependencies and node_modules are not the codebase, and including them would
// inflate the denominator and flatter every ratio computed from it.
func measureCorpus(ctx context.Context, opts Options, repoDir string) (corpusSize, []string, error) {
	var size corpusSize
	var warnings []string

	out, err := gitScalar(ctx, opts.Runner, repoDir, "ls-files", "-z")
	if err != nil {
		return size, nil, fmt.Errorf("list tracked files (the scale benchmark needs a git repository): %w", err)
	}
	paths := strings.Split(strings.TrimRight(out, "\x00"), "\x00")
	skipped := 0
	for _, rel := range paths {
		rel = strings.TrimSpace(rel)
		if rel == "" {
			continue
		}
		size.tracked++
		if !isCountableSourcePath(rel) {
			continue
		}
		lines, bytes, err := countFileLines(filepath.Join(repoDir, filepath.FromSlash(rel)))
		if err != nil {
			skipped++
			continue
		}
		size.files++
		size.lines += lines
		size.bytes += bytes
	}
	if skipped > 0 {
		// Name it rather than silently shrinking the denominator.
		warnings = append(warnings, fmt.Sprintf("%d tracked file(s) could not be read and are not counted", skipped))
	}
	if size.lines == 0 {
		warnings = append(warnings, "no source lines were counted; ratios per line are omitted")
	}
	return size, warnings, nil
}

// isCountableSourcePath excludes what is in the tree but is not the codebase.
func isCountableSourcePath(rel string) bool {
	rel = filepath.ToSlash(rel)
	for _, prefix := range []string{"vendor/", "node_modules/", "third_party/", "testdata/"} {
		if strings.HasPrefix(rel, prefix) || strings.Contains(rel, "/"+prefix) {
			return false
		}
	}
	switch strings.ToLower(filepath.Ext(rel)) {
	case ".png", ".jpg", ".jpeg", ".gif", ".webp", ".ico", ".pdf", ".zip", ".gz", ".tar",
		".mp4", ".mov", ".woff", ".woff2", ".ttf", ".otf", ".bin", ".wasm", ".so", ".dylib", ".a":
		return false
	}
	return true
}

func countFileLines(path string) (lines, bytes int64, err error) {
	info, err := os.Lstat(path)
	if err != nil {
		return 0, 0, err
	}
	// A symlink's target is counted under its own path if it is tracked;
	// following it here would count the same content twice.
	if !info.Mode().IsRegular() {
		return 0, 0, fmt.Errorf("not a regular file")
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return 0, 0, err
	}
	bytes = int64(len(data))
	if bytes == 0 {
		return 0, 0, nil
	}
	for _, b := range data {
		if b == '\n' {
			lines++
		}
	}
	// A final line without a trailing newline is still a line.
	if data[len(data)-1] != '\n' {
				verb = "would import"
			}
			fmt.Fprintf(cmd.OutOrStdout(), "%s %d of %d memories from %s\n", verb, report.Imported, report.Read, report.Source)
			if report.SkippedText > 0 {
				fmt.Fprintf(cmd.OutOrStdout(), "  %d skipped: no memory text\n", report.SkippedText)
			}
			if report.Superseded > 0 {
				fmt.Fprintf(cmd.OutOrStdout(), "  %d already superseded at the source; imported as superseded\n", report.Superseded)
			}
			for _, note := range report.Unsupported {
				fmt.Fprintf(cmd.OutOrStdout(), "  not carried over: %s\n", note)
			}
			return nil
		},
	}
	cmd.Flags().StringVar(&source, "source", "mem0", "Source tool the export came from (mem0)")
	cmd.Flags().StringVar(&file, "file", "", "Path to the export file, or - for stdin")
	cmd.Flags().StringVar(&prefix, "path-prefix", "project.imported", "Taxonomy prefix imported facts are filed under")
	cmd.Flags().StringVar(&branch, "branch", "", "Branch to import onto (default: current)")
	cmd.Flags().BoolVar(&dryRun, "dry-run", false, "Report what would be imported without writing")
	cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit the report as JSON")
	return cmd
}

// readImportFile reads an export, bounded.
//
// The file is named by the operator, but that is not a reason to read it
// unboundedly: a 16 GiB export is a memory-exhaustion problem whether it was
// chosen deliberately or by mistake, and a FIFO or device file at that path
// blocks forever rather than failing. safeReadFile and safeReadAll are what
// every other untrusted-input surface here uses, for exactly these two
// reasons.
func readImportFile(path string) ([]byte, error) {
	if strings.TrimSpace(path) == "-" {
		return safeReadAll(os.Stdin, maxManifestBytes, "import file from stdin")
	}
	data, err := safeReadFile(path, maxManifestBytes)
	if err != nil {
		return nil, fmt.Errorf("read export: %w", err)
	}
	return data, nil
}
#!/bin/sh
# One command that installs the Entire code-intelligence system from source.
#
#   scripts/install.sh
#
# What it does to the machine, and nothing else:
#
#   1. builds the entire-graph semantic provider and registers it with the
#      Entire CLI (`entire plugin install`),
#   2. builds entire-brain and registers it the same way,
#   3. writes the default entire-brain plugin configuration
#      (`entire brain config init`),
#   4. runs `entire brain doctor`.
#
# It does NOT require entire-graph to be arranged as a sibling of this checkout,
# and it does not care what this checkout is called. The provider is resolved by
# three routes, and the route actually taken is printed:
#
#   1. $ENTIRE_GRAPH_DIR, when set. An explicit override is never second-guessed:
#      if it does not hold an entire-graph checkout the run stops there rather
#      than quietly installing something else.
#   2. A checkout already on this machine -- siblings of this checkout (and of
#      the main worktree, when this is a linked one), the route-3 cache, and the
#      usual source directories under $HOME. A candidate counts only when it
#      really is entire-graph (cmd/entire-graph and scripts/install-local.sh are
#      both present), so a directory that merely has the name is skipped.
#   3. Otherwise a shallow clone of the public entire-graph repository into a
#      cache directory this script owns, built from there.
#
# Prerequisites are checked before anything is built, and every missing one is
# reported in one pass with the fix for it.
#
# Environment:
#   ENTIRE_GRAPH_DIR=<path>    use this entire-graph checkout; skip discovery
#   ENTIRE_GRAPH_REPO=<url>    clone route 3 from somewhere else
#   ENTIRE_GRAPH_CACHE=<path>  where route 3 clones to
#                              (default $XDG_CACHE_HOME/entire-brain/entire-graph)
#   ENTIRE_INSTALL_OFFLINE=1   never reach the network; fail rather than clone
