offline=${ENTIRE_INSTALL_OFFLINE:-}
graph_cache=${ENTIRE_GRAPH_CACHE:-"${XDG_CACHE_HOME:-${HOME:-$brain_root}/.cache}/entire-brain/entire-graph"}
graph_cache_marker=.entire-brain-managed-cache

