package cli

import (
	"context"
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/spf13/cobra"
)

const (
	recallEngineLexicalHandrolled = "lexical_handrolled"
	recallEngineModel2VecRRF      = "model2vec_rrf"
	recallEngineEmbeddingGemmaRRF = "embeddinggemma_rrf"
)

// recallRetrievalEngine is emitted with recall --json. The effective engine is
// present only when it can be established from the path rankFactsFused actually
// took. Requested environment alone is never sufficient: a failed Ollama
// selection may be a real Model2Vec run, and a selected server may still fail
// the real query or a document embedding after its startup probe.
type recallRetrievalEngine struct {
	SchemaVersion         int    `json:"schema_version"`
	EffectiveEngine       string `json:"effective_engine,omitempty"`
	IdentityVerified      bool   `json:"identity_verified"`
	SemanticRequested     bool   `json:"semantic_requested"`
	SemanticApplied       bool   `json:"semantic_applied"`
	SemanticAvailable     bool   `json:"semantic_available"`
	BM25Enabled           bool   `json:"bm25_enabled"`
	BM25Applied           bool   `json:"bm25_applied"`
	FallbackUsed          bool   `json:"fallback_used"`
	RequestedEmbedder     string `json:"requested_embedder,omitempty"`
	SelectedEmbedderID    string `json:"selected_embedder_id,omitempty"`
	EmbedderID            string `json:"embedder_id,omitempty"`
	EmbeddingModelID      string `json:"embedding_model_id,omitempty"`
	EmbeddingDimension    *int   `json:"embedding_dimension,omitempty"`
	VectorCount           *int   `json:"vector_count,omitempty"`
	VectorCandidateCount  *int   `json:"vector_candidate_count,omitempty"`
	LoadedVectorCount     *int   `json:"loaded_vector_count,omitempty"`
	ResidentVectorCount   *int   `json:"resident_vector_count,omitempty"`
	VectorCacheBackend    string `json:"vector_cache_backend,omitempty"`
	VectorCachePath       string `json:"vector_cache_path,omitempty"`
	VectorCacheReadOnly   *bool  `json:"vector_cache_read_only,omitempty"`
	IdentityFailureReason string `json:"identity_failure_reason,omitempty"`
}

type vectorCacheDescriptor interface {
	vectorCacheBackend() string
	vectorCachePath() string
}

func recallIntPtr(v int) *int    { return &v }
func recallBoolPtr(v bool) *bool { return &v }
func requestedEmbedderName() string {
	requested := strings.ToLower(strings.TrimSpace(os.Getenv("ENTIRE_BRAIN_EMBEDDER")))
	if requested == "" {
		return "bundled_model2vec"
	}
	return requested
}

// recallRetrievalIdentity turns runtime observations into the three primary
// benchmark identities. Unsupported combinations (currently the optional BM25
// factor), malformed vectors, partial document embedding, and unknown/custom
// embedders deliberately have no effective_engine so consumers fail closed.
func recallRetrievalIdentity(semanticRequested, readOnlyCache bool, rr *semanticReranker) recallRetrievalEngine {
	identity := recallRetrievalEngine{
		SchemaVersion:     1,
		SemanticRequested: semanticRequested,
		RequestedEmbedder: requestedEmbedderName(),
		BM25Enabled:       factsBM25Enabled(),
	}


func readFactFilesManifest(dir string) (factFilesManifest, error) {
	var manifest factFilesManifest
	// The read follows symlinks just as the write would, so a link planted at
	// the manifest would feed this export a reconciliation record from outside
	// --dir — and then act on it, deleting whatever it named. A symlinked
	// manifest reads as no manifest, which prunes nothing.
	if err := rejectExistingSymlinkPathComponents(dir, factFilesManifestName); err != nil {
		return manifest, nil
	}
	data, err := os.ReadFile(filepath.Join(dir, factFilesManifestName))
	if err != nil {
		// No manifest means either a first run or a directory this command has
		// never written to. Removing nothing is the only safe reading of both.
		return manifest, nil
	}
	if len(bytes.TrimSpace(data)) == 0 {
		return manifest, nil
	}
	if err := json.Unmarshal(data, &manifest); err != nil {
		// Treating a corrupt manifest as empty is the worst option available:
		// every file a previous export wrote becomes permanently unremovable,
		// nothing says so, and the directory quietly stops meaning what the
		// command says it means. Refusing is recoverable in one step, and the
		// error says which step.
		return manifest, fmt.Errorf("%s is unreadable (%w); delete it to start a fresh export, "+
			"which will leave any files a previous run wrote in place", factFilesManifestName, err)
	}
	return manifest, nil
}

// pruneStaleFactFiles removes files the last export wrote and this one did not.
//
// A fact that was retracted, or whose taxonomy path moved, leaves a file behind
// otherwise — and a grep over the export then returns something the brain no
// longer believes, presented exactly like something it does.
func pruneStaleFactFiles(dir string, previous factFilesManifest, written map[string]bool) error {
	var dirs []string
	for _, rel := range previous.Files {
		if written[rel] {
			continue
			t.Fatalf("the export deleted %s, which it did not write", filepath.Base(path))
		}
	}
}

// The manifest is a JSON file sitting inside a directory the user controls, so
// its contents are input, not a trusted record. An entry pointing outside the
// export root would turn the next export into a delete of whatever it names.
func TestExportEscapingManifestEntryIsRefused(t *testing.T) {
	root := t.TempDir()
	outside := filepath.Join(root, "outside.md")
	if err := os.WriteFile(outside, []byte("not in the export"), 0o644); err != nil {
		t.Fatal(err)
	}
	dir := filepath.Join(root, "export")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	// Slash-separated literals, not filepath.Join: on Windows Join emits
	// backslashes, which are invalid JSON escapes — the manifest would be
	// corrupt rather than escaping, and the test would exercise the
		t.Fatalf("main export: %v", err)
	}
	mainFile := filepath.Join(dir, "architecture", "api", "ports", factFileName(onMain.ID))
	if _, err := os.Stat(mainFile); err != nil {
		t.Fatalf("setup: %v", err)
	}

	result, err := writeFactFiles(dir, "feature", []factRecord{onFeature})
	if err != nil {
		t.Fatalf("feature export: %v", err)
	}
	if _, err := os.Stat(mainFile); err != nil {
		t.Fatal("exporting a second branch into the same directory deleted the first branch's files")
	}
	// Silence would be worse than the deletion in one way: the directory now
	// holds two branches' facts and nothing says so.
	if len(result.Warnings) == 0 {
		t.Fatal("the directory now holds two branches' exports and nothing said so")
	}
	if !strings.Contains(strings.Join(result.Warnings, " "), "main") {
		t.Fatalf("the warning does not name the other branch: %v", result.Warnings)
	}
}

// And re-exporting the SAME branch must still reconcile, or the branch check
// has disabled pruning rather than scoping it.
func TestExportStillPrunesWithinOneBranch(t *testing.T) {
	dir := t.TempDir()
	keep := factRecord{ID: "fact:aaaa1111", Paths: []string{"architecture.api.ports"}, Text: "Ports start at 8000.", Status: factStatusActive}
	drop := factRecord{ID: "fact:bbbb2222", Paths: []string{"constraints.retry.policy"}, Text: "Retries stop at three.", Status: factStatusActive}

	if _, err := writeFactFiles(dir, "main", []factRecord{keep, drop}); err != nil {
		t.Fatalf("first export: %v", err)
	}
	stale := filepath.Join(dir, "constraints", "retry", "policy", factFileName(drop.ID))
	if _, err := os.Stat(stale); err != nil {
		t.Fatalf("setup: %v", err)
	}
	if _, err := writeFactFiles(dir, "main", []factRecord{keep}); err != nil {
		t.Fatalf("second export: %v", err)
	}
	if _, err := os.Stat(stale); err == nil {
		t.Fatal("a retracted fact's file survived a same-branch re-export")
	}
}

// A warning on the result is only useful if the command prints it.
func TestFactsFilesCommandPrintsCrossBranchWarnings(t *testing.T) {
	now := time.Date(2026, 9, 21, 12, 0, 0, 0, time.UTC)
	opts, brainDir, branch := rememberReviveEnv(t, now)
	dir := t.TempDir()

	// A previous export recorded for a different branch.
	if _, err := writeFactFiles(dir, "some-other-branch", []factRecord{
		{ID: "fact:aaaa1111", Paths: []string{"architecture.api.ports"}, Text: "From elsewhere.", Status: factStatusActive},
	}); err != nil {
		t.Fatalf("seed export: %v", err)
	}
	if err := withBrainWriteLock(brainDir, func() error {
		return writeFacts(brainDir, branch, []factRecord{
			{ID: "fact:bbbb2222", Paths: []string{"constraints.retry.policy"}, Text: "Here.", Branch: branch, Status: factStatusActive, CreatedAt: now, UpdatedAt: now},
		})
	}); err != nil {
		t.Fatalf("seed facts: %v", err)
	}

	cmd := newFactsFilesCommand(opts)
	out, errOut := &bytes.Buffer{}, &bytes.Buffer{}
	cmd.SetOut(out)
	cmd.SetErr(errOut)
	cmd.SetContext(context.Background())
	if err := cmd.Flags().Set("dir", dir); err != nil {
		t.Fatal(err)
	}
	if err := cmd.RunE(cmd, nil); err != nil {
		t.Fatalf("facts files: %v", err)
	}
	if !strings.Contains(errOut.String(), "some-other-branch") {
		t.Fatalf("the command did not report that the directory holds another branch's export: %q", errOut.String())
	}

