// GC prunes retracted facts and superseded facts older than the retention
// window, and reports taxonomy-orphaned facts (whose top-level category no
// longer exists) without ever deleting them. Orphans that are also prunable
// (retracted/old-superseded) are pruned; active orphans are kept and reported.
//
// Whether a fact's paths are still known is injected via knownTopLevel so the
// core stays free of the taxonomy loader: knownTopLevel(path) reports whether
// path's top-level category still exists.
func GC(facts []Record, knownTopLevel func(path string) bool, now time.Time, retention time.Duration) GCResult {
	cutoff := now.Add(-retention)
	var result GCResult
	for _, f := range facts {
		if !allPathsKnown(f, knownTopLevel) {
			result.Orphans = append(result.Orphans, f)
		}
		switch f.Status {
		case StatusRetracted:
			result.Pruned = append(result.Pruned, f)
			continue
		case StatusSuperseded:
			if f.UpdatedAt.Before(cutoff) {
				result.Pruned = append(result.Pruned, f)
				continue
			}
		}
		result.Kept = append(result.Kept, f)
	}
	return result
}

// allPathsKnown reports whether every path's top-level category is known
// according to the injected predicate.
func allPathsKnown(f Record, knownTopLevel func(path string) bool) bool {
	for _, p := range f.Paths {
		if !knownTopLevel(p) {
			return false
		}
	}
	return true
}
type factImportReport struct {
	Source      string   `json:"source"`
	File        string   `json:"file"`
	Read        int      `json:"read"`
	Imported    int      `json:"imported"`
	SkippedText int      `json:"skipped_empty_text"`
	Superseded  int      `json:"marked_superseded"`
	Unsupported []string `json:"unsupported,omitempty"`
	DryRun      bool     `json:"dry_run"`
}

// memoriesToFacts converts normalised memories into fact records. now supplies
// the timestamp for any memory whose source carried none, so an undated import
// is dated at import time rather than at the zero value.
func memoriesToFacts(memories []importedMemory, skipped int, source, prefix, branch string, now time.Time) ([]factRecord, factImportReport) {
	// Read is what the file contained, not what survived parsing: "3 of 3"
	// when the file held four is exactly the silent drop this reports against.
	report := factImportReport{Source: source, Read: len(memories) + skipped, SkippedText: skipped}
	unsupported := map[string]bool{}
	facts := make([]factRecord, 0, len(memories))
	// Supersession is resolved after the loop, because a memory can be
	// The source had already replaced one memory. Importing it as active would
	// resurrect something its owner retired.
	superseded := 0
	for _, fact := range facts {
		if fact.Status == "superseded" {
			superseded++
		}
	}
	if superseded != 1 || report.Superseded != 1 {
		t.Fatalf("superseded = %d (report %d), want 1", superseded, report.Superseded)
	}

	// Brain has no TTL and does not scope by user. Both must be named, not
	// quietly discarded: an expiry that silently vanishes turns a memory its
	// owner scheduled to disappear into one that never does.
	joined := strings.Join(report.Unsupported, " | ")
	for _, want := range []string{"expiration_date", "user_id"} {
		if !strings.Contains(joined, want) {
			t.Fatalf("report does not mention %q: %v", want, report.Unsupported)
		}
	}
}

func TestImportedFactsAreFiledSomewhereObvious(t *testing.T) {
	memories, skipped, err := parseMem0([]byte(mem0Export))
	if err != nil {
		t.Fatalf("parse: %v", err)
	}
	facts, _ := memoriesToFacts(memories, skipped, "mem0", "project.imported", "main", time.Now())
	for _, fact := range facts {
		// Foreign categories are free text and cannot be trusted to land under
		// a known top level, so everything stays under the prefix until a human
		// reclassifies it.
		if !strings.HasPrefix(fact.Paths[0], "project.imported.") {
			t.Fatalf("%s filed at %q, outside the import prefix", fact.ID, fact.Paths[0])
		}
	}
	// "Team Process" has to survive as a usable segment. Underscore, not
	// hyphen: the taxonomy pattern admits only [a-z0-9_], so the hyphenated
	// form this test originally expected was a path normalisation would drop,
	// leaving the record with no paths at all.
	found := false
	for _, fact := range facts {
		if fact.Paths[0] == "project.imported.team_process" {
			found = true
		}
	}
	if !found {
		t.Fatalf(`category "Team Process" did not become project.imported.team_process: %q`, facts[0].Paths)
	}
}

